import React from "react";

export default function RichText({ content, as: Tag = "span", className }) {
  if (content == null) return null;

  // If string, treat as trusted internal HTML (only use with internal content)
  if (typeof content === "string") {
    return (
      <Tag
        className={className}
        dangerouslySetInnerHTML={{ __html: content }}
      />
    );
  }

  // Otherwise assume it's a ReactNode (JSX)
  return <Tag className={className}>{content}</Tag>;
} 